'use strict';

/**
* Computes the zero-order Bessel function of the first kind for a single-precision floating-point number.
*
* @module @stdlib/math/base/special/besselj0f
*
* @example
* var j0f = require( '@stdlib/math/base/special/besselj0f' );
*
* var v = j0f( 0.0 );
* // returns 1.0
*
* v = j0f( 1.0 );
* // returns ~0.765
*
* v = j0f( Infinity );
* // returns 0.0
*
* v = j0f( -Infinity );
* // returns 0.0
*
* v = j0f( NaN );
* // returns NaN
*/

// MODULES //

var j0f = require( './main.js' );


// EXPORTS //

module.exports = j0f;
